def _tokens(message):
    return len(message['content'].split())


def trim_history(messages, budget):
    system, rest = [], list(messages)
    if rest and rest[0]['role'] == 'system':
        system, rest = [rest[0]], rest[1:]
    remaining = budget - sum(_tokens(m) for m in system)
    if remaining < 0:
        raise ValueError('system prompt alone exceeds the budget')
    tail = []
    for m in reversed(rest):
        t = _tokens(m)
        if t > remaining:
            break
        tail.append(m)
        remaining -= t
    tail.reverse()
    while tail and tail[0]['role'] == 'assistant':
        tail.pop(0)
    return system + tail
